    ORDER BY inspection.id FOR UPDATE OF inspection
  LOOP
    SELECT run.id,run.manifest_id,run.display_status,run.stats INTO replacement
    FROM analysis_runs run JOIN analysis_releases release ON release.release_id=run.release_id
    WHERE run.inspection_id=target.id AND run.object_id=target.object_id AND run.mode='NORMAL'
      AND release.content_json->>'purpose' IS DISTINCT FROM 'SOURCE_AUDIT_ONLY'
    ORDER BY run.started_at DESC,run.id DESC LIMIT 1;
    UPDATE inspections SET active_run_id=replacement.id,working_manifest_id=replacement.manifest_id,
      row_version=row_version+1,updated_at=now()
      WHERE id=target.id AND lifecycle='OPEN';
    UPDATE objects SET display_status=COALESCE(replacement.display_status,'UPLOADING'),
      stats=COALESCE(replacement.stats,'{"total":132,"unsupported":0,"candidates":0,"confirmed":0,"negativeVerified":0,"notComparable":0,"clarification":0,"suspicion":0}'::jsonb),
